WITH src AS (SELECT * FROM store_sales WHERE revenue <= 1600), revenue_bucket_summary AS (SELECT CASE WHEN revenue >= 4500 THEN 'high' WHEN revenue >= 2000 THEN 'mid' ELSE 'low' END AS revenue_bucket, ROUND(STDDEV(units), 2) AS stddev_units, MAX(revenue) AS max_revenue FROM src GROUP BY CASE WHEN revenue >= 4500 THEN 'high' WHEN revenue >= 2000 THEN 'mid' ELSE 'low' END) SELECT revenue_bucket, stddev_units, max_revenue FROM revenue_bucket_summary WHERE stddev_units < 65 ORDER BY stddev_units DESC, max_revenue DESC;
